 boolean action(String n){if("home".equals(n))return performGlobalAction(GLOBAL_ACTION_HOME);if("back".equals(n))return performGlobalAction(GLOBAL_ACTION_BACK);if("recents".equals(n))return performGlobalAction(GLOBAL_ACTION_RECENTS);AccessibilityNodeInfo r=getRootInActiveWindow();if(r==null)return false;int a="up".equals(n)?AccessibilityNodeInfo.ACTION_SCROLL_BACKWARD:"down".equals(n)?AccessibilityNodeInfo.ACTION_SCROLL_FORWARD:-1;if(a!=-1){boolean ok=r.performAction(a);r.recycle();return ok;}AccessibilityNodeInfo f=r.findFocus(AccessibilityNodeInfo.FOCUS_ACCESSIBILITY);if(f==null)f=r;boolean ok="ok".equals(n)&&f.performAction(AccessibilityNodeInfo.ACTION_CLICK);if(f!=r)f.recycle();r.recycle();return ok;}
 boolean typeText(String t){AccessibilityNodeInfo r=getRootInActiveWindow();if(r==null)return false;AccessibilityNodeInfo f=r.findFocus(AccessibilityNodeInfo.FOCUS_INPUT);if(f==null)f=r.findFocus(AccessibilityNodeInfo.FOCUS_ACCESSIBILITY);if(f==null){r.recycle();return false;}Bundle b=new Bundle();b.putCharSequence(AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE,t);boolean ok=f.performAction(AccessibilityNodeInfo.ACTION_SET_TEXT,b);if(f!=r)f.recycle();r.recycle();return ok;}
